{
  "cards": [
    {
      "source_id": "CPA2019-S2-7",
      "how_it_may_relate": "This provision helps establish whether you count as a consumer after buying the mobile phone from ShopKart for personal use."
    },
    {
      "source_id": "CPA2019-S2-10",
      "how_it_may_relate": "This definition of a defect applies to the faulty mobile phone delivered to you."
    },
    {
      "source_id": "CPA2019-S2-47-viii",
      "how_it_may_relate": "Refusing or delaying a refund for a returned defective item after the specified period or 30 days may be considered an unfair trade practice."
    },
